-- The community search for London and Philadelphia, a wider pass (Sean, 2026-10-28: "run the community search for London and
-- Philadelphia too"). 60 Google Places text searches (request ids 225364 to 225423): animal rescues in 20 London boroughs plus cat,
-- dog, rabbit, bird, horse and farm animal rescues, sanctuaries, animal rights groups and Vegan charities; animal rescues in 15
-- Pennsylvania cities (the Philadelphia chapter is the whole state) plus sanctuaries, horse, rabbit, bird and pig rescues and Vegan
-- and animal rights groups statewide. Same filters as 20261028_community_search_other_chapters.sql, plus: RSPCA left out (set aside
-- for its farm labels), and sellers, sitters, trainers, cafes and services that matched by name. Google files much of Greater
-- London under its postal town (Croydon, Bromley, Enfield...), so those count as London and carry communities ['london'], since
-- the London chapter matches the city London; places in Kent, Surrey, Essex and Hertfordshire are left out.
-- 123 quarantined, waiting in Business outreach > New places > Ready to list: London 12, Philadelphia 111. Nothing went live.
-- This file is the record: net._http_response keeps the search responses only for a few hours, so it does nothing if run later.
with m(rid) as (select r0.id from net._http_response r0 where r0.id between 225364 and 225423 and r0.content like '{%' and r0.content like '%"places"%'),
p0 as (select distinct on (e.p->>'id') e.p from m join net._http_response r on r.id = m.rid cross join jsonb_array_elements(coalesce((r.content::jsonb)->'places','[]'::jsonb)) e(p) order by e.p->>'id', m.rid),
p as (select p, p->'displayName'->>'text' nm, coalesce(p->'primaryTypeDisplayName'->>'text','') ty,
    (select string_agg(c->>'longText', ' ') from jsonb_array_elements(p->'addressComponents') c where c->'types' ?| array['street_number','route']) street,
    coalesce((select c->>'longText' from jsonb_array_elements(p->'addressComponents') c where c->'types' ? 'locality' limit 1),(select c->>'longText' from jsonb_array_elements(p->'addressComponents') c where c->'types' ? 'postal_town' limit 1),(select replace(c->>'longText','The Bronx','Bronx') from jsonb_array_elements(p->'addressComponents') c where c->'types' ? 'sublocality_level_1' limit 1)) locality,
    (select c->>'shortText' from jsonb_array_elements(p->'addressComponents') c where c->'types' ? 'administrative_area_level_1' limit 1) st,
    (select c->>'longText' from jsonb_array_elements(p->'addressComponents') c where c->'types' ? 'postal_code' limit 1) zip,
    (select c->>'shortText' from jsonb_array_elements(p->'addressComponents') c where c->'types' ? 'country' limit 1) country
  from p0 where coalesce(p->>'businessStatus','OPERATIONAL') = 'OPERATIONAL'),
f as (select * from (select p.*, case when country='GB' and locality = any(array['London','Barnet','Bromley','Croydon','Enfield','Harrow','Richmond','Mitcham','Thornton Heath','Welling','Woodford Green','Worcester Park','Feltham','Orpington','Chislehurst','Keston','Downe','Biggin Hill','Harefield','Kingston upon Thames','Sutton','Twickenham','Hounslow','Ilford','Romford','Wembley','Uxbridge','Bexleyheath','Sidcup','Carshalton','Wallington','Purley','Hayes','Southall','Edgware','Pinner','Isleworth','Morden','New Malden','Surbiton','Hornchurch','Dagenham','Barking','Erith','Beckenham','West Wickham','South Croydon','Coulsdon','Teddington','Hampton','Greenford','Northolt','Ruislip','Stanmore']) then 'london' when country='US' and st='PA' then 'philadelphia' end hub from p) p0x
  where hub is not null
    and ty not in ('Zoo','Tourist Attraction','Park','Museum','Cultural Center','Event Venue','Restaurant','Veterinary Care','Wildlife Park','Wildlife Refuge','Nature Preserve','Store','Pet Store','Thrift Store','Cemetery','Government Office','Wholesaler','Pet Boarding Service','Food Store')
    and (ty in ('Pet Care','Farm','Farmstay') or nm ~* 'animal|pet|paw|dog|cat|kitt|feline|rescue|humane|spca|sanctuar|refuge|ranch|vegan|\mveg|hound|mutt|pup|equine|pig|poodle|ferret|greyhound|pitbull|primate|creature|critter|tail|fur|hoove|kidden|meow|roar|rights')
    and nm !~* '(zoo|petting|animal services|animal control|county animal|police animal|city of |care & control|care and control|animal care and adoption|animal care & adoption|county humane society thrift|clinic|spay|wildlife|nature conservancy|conservation|wild virginia|estuary|nonprofit advancement|paws for people|rescue mission|rescue ministr|hunger|lawyers|pet advocacy|american humane|national colonial|old maryland farm|big purple barn|cow cuddles|green meadows|kinder farm|dragonfly acres|creatures great|coverdale|james farm|story hill|maymont|pactamere|heritage farm|wild goats|dairy|wild kid acres|grace haven|furry friends farm|redemptive love farm|french bulldog|cane corso|monkey rehome|hotel for dogs|joe and kloe|luv.n arms|cat cafe|everypet|earth pets|exterminator|infinity acres|aquarium|memorial park|wvu office|adoption authority|florida adoptions|angels for allison|be the solution|lifee|healing hearts|r&r loving|whole h\.e\.a\.r\.t|sacred friends|^acca$|we can be heroes|fetch a cure|petland|petsmart|catty shack|wild animal|odessa|rose bridge|little farm|barnyard besties|3 palms|four acres|providence animal|southeastern pa|protective services|tri-state bird|behavior and training|pets on wheels)'
    and nm !~* '(animal centre coffee|animal jobs direct|^cd homes|petbae|petpals|tails\.com|puppies for|koukla|love pets home|kitten for adoption|^pet rescue london$|puppy love pet|take-a-paws|animal welfare management|bunnies by|rabbitry|davis dog farm|gangster vegan|vegan confection|the happy vegan|house of dashies|^no$|doylestowndogs|puppy pi|the dogs den|river rescue and emergency|cat nook cafe|black cat market)'
    and nm !~* '(rspca|search & rescue|betta fish|shelters and shelves|hillsborough county pet resource center|manatee|bobcat|wild bird|cell dogs|seaworld|^pit bull adoption|waggles|maxx and me|animal welfare japan|mainecoon|royal humane|charities fair|humane world for animals|^aspca$|harbor animal care|animal care services|animal care center|burbank animal shelter|city east valley|north central animal shelter|south la animal shelter|west los angeles animal shelter|west valley animal shelter|yonkers animal shelter|petradar|service animal foundation|pet alert warning|pretty pets|^p3t lif3$|international rescue committee|butterfly mural|renegade rex|cat lounge|humane animal rescue pittsburgh$|bobbi and the strays)'
    and nm !~* '(zoo|petting|u-?pick|alpaca|safari|adventure|edventure|animal park|park and farm|city farm|urban farm|children''s farm|park farm|farmstead|fox chase farm|awbury|goat yoga|nature conservancy|audubon|hunger|food well|feeding ga|make a difference|volunteers for community|thrive dc|new york cares|women beyond|community action|helping hand|unstoppable|wissahickon|food rescue|livewell|eco foundation|we love philly|new sanctuary movement|animal services|clinic|world wildlife fund|greenpeace|peoples trust|conservation|wildlife alliance|wildlife sustainability|ideas for us|pet sustainability|pet advocacy|institute for humane studies|vegan blaze|bearded vegan|kfar saba|care farm|exotic|tamworth|animal action greece|vetpaw|national colonial|kinder farm|old maryland farm|cow cuddles|bell family|terra verde|wildflower farm|green meadows|amazing animals|river ranch|beautiful creatures|jungle adventures|animal reserve|tinez|redstone|madagascar|panther ridge|oatland|goat farm arts|creekwater|half moon|wild animal|untamed|chestatee|noah.s ark|yellow river|little creek|philly goat|rose bridge|sanctuary farm phila|tyler|ross mill|gress mountain|big purple barn|dragonfly acres|vegan friendly uk|jewish vegetarian|adoption service|labelle|sant. d.or|star eco|reptacular|animal tracks|wildlife learning|shambala|forever wild|moonwater|farm friendz|farralone|wildlife center|mudchute|hackney|spitalfields|vauxhall|stepney|kentish|surrey docks|freightliners|belmont|hounslow|crystal palace|lee valley|woodlands farm|maryon|animal assisted|big heart ranch|aware wildlife|wild nest|wildlife refuge|wildlife sanctuary|wellington|critter creek sanctuary ranch|elwyn)'),
n as (select f.*, case when nm ~* 'faithful friends|purringpals|meow or never|house with a heart|luna.s house|hart for animals|tails of hope|rude ranch|rottweiler rescue ranch|puppy hill|cj acres' then 'Rescues'
    when nm ~* 'sanctuar|refuge|ranch|farm' then 'Sanctuaries'
    when nm ~* 'rescue|humane|spca|shelter|paws|adoption|haven|league|pets|dog|cat|kitt|mutt|pup|hound|feline|ferret|poodle|greyhound|pitbull|barcs|animal (aid|alliance|trust|home|refuge|project|friends|welfare|outreach)' then 'Rescues' else 'Nonprofits' end cat
  from f where not exists (select 1 from listings l where l.google_place_id = f.p->>'id' or (regexp_replace(lower(l.name),'[^a-z0-9]','','g') = regexp_replace(lower(f.nm),'[^a-z0-9]','','g')))),
n1 as (select distinct on (lower(trim(left(nm,140))), lower(coalesce(locality,'')), st) * from n
  order by lower(trim(left(nm,140))), lower(coalesce(locality,'')), st, (p->>'userRatingCount')::int desc nulls last),
ins as (insert into listings (name, category, specialty, description, status, website, phone, location, address_street, address_city, address_state, address_zip,
    initials, crawl_source, vegan_status, communities, details)
  select left(nm, 140), 'Uncategorized', '', '', 'quarantined', coalesce(p->>'websiteUri', ''), p->>'nationalPhoneNumber',
    concat_ws(', ', locality, case when country='GB' then null else st end), street, locality, case when country='GB' then null else st end, zip,
    upper(left(regexp_replace(nm, '[^A-Za-z]', '', 'g'), 2)), 'community-search', null, case when hub = 'london' and locality <> 'London' then array['london'] else '{}' end,
    jsonb_build_object('community_search', jsonb_build_object('hub', hub, 'guess', cat, 'at', now(), 'google_type', p->'primaryTypeDisplayName'->>'text', 'place_id', p->>'id'))
  from n1 returning id, details),
bc as (insert into ve_backlog_checks (listing_id, track, stage, verdict, reason, community_slug, city_guess, place, checked_at)
select ins.id, 'google', 'done', 'list',
  'From the community search: looks like ' || case n.cat when 'Rescues' then 'a rescue' when 'Sanctuaries' then 'a sanctuary' else 'a nonprofit' end || ' (' || coalesce(nullif(n.ty,''), 'Google') || '). Add it under Rescues, Sanctuaries or Nonprofits, or set it aside (Logan, 2026-10-28, London and Philadelphia community search)',
  n.hub, n.locality,
  jsonb_build_object('id', n.p->>'id', 'name', n.nm, 'address', n.p->>'formattedAddress', 'street', n.street, 'city', n.locality,
    'state', case when n.country='GB' then null else n.st end, 'zip', n.zip, 'country', n.country, 'lat', (n.p->'location'->>'latitude')::float, 'lng', (n.p->'location'->>'longitude')::float,
    'status', coalesce(n.p->>'businessStatus', 'OPERATIONAL'), 'rating', (n.p->>'rating')::float, 'reviews', (n.p->>'userRatingCount')::int, 'website', n.p->>'websiteUri',
    'phone', n.p->>'nationalPhoneNumber', 'type_name', n.ty, 'types', n.p->'types'),
  now()
from ins join n1 n on n.p->>'id' = ins.details->'community_search'->>'place_id' returning community_slug)
select community_slug, count(*) from bc group by 1 order by 1;